<template><div class="counselor-layout"><div v-if="!isMobile" class="desktop-layout"><aside class="sidebar"><div class="logo">辅导员系统</div><el-menu :default-active="route.path" router><el-menu-item index="/"><el-icon><HomeFilled/></el-icon><span>首页</span></el-menu-item><el-menu-item index="/psych"><el-icon><Opportunity/></el-icon><span>心理评估</span></el-menu-item><el-menu-item index="/contacts"><el-icon><UserFilled/></el-icon><span>通讯录</span></el-menu-item><el-menu-item index="/notifications"><el-icon><Bell/></el-icon><span>消息中心</span><el-badge v-if="unread" :value="unread" class="menu-badge"/></el-menu-item><el-menu-item index="/profile"><el-icon><Setting/></el-icon><span>个人中心</span></el-menu-item></el-menu><div class="sidebar-footer"><el-button type="danger" text @click="logout">退出登录</el-button></div></aside><main class="main-content"><router-view/></main></div><main v-else class="mobile-content"><router-view/></main><nav v-if="isMobile" class="mobile-nav"><router-link to="/" class="nav-item"><el-icon><HomeFilled/></el-icon><span>首页</span></router-link><router-link to="/psych" class="nav-item"><el-icon><Opportunity/></el-icon><span>心理评估</span></router-link><router-link to="/contacts" class="nav-item"><el-icon><UserFilled/></el-icon><span>通讯录</span></router-link><router-link to="/notifications" class="nav-item"><el-badge :value="unread||''" :hidden="!unread"><el-icon><Bell/></el-icon></el-badge><span>消息</span></router-link><router-link to="/profile" class="nav-item"><el-icon><Setting/></el-icon><span>我的</span></router-link></nav></div></template>
<script setup>import{ref,onMounted,onUnmounted}from'vue';import{useRoute,useRouter}from'vue-router';import{useAuthStore}from'../../stores/auth';import api from'../../utils/request';const route=useRoute(),router=useRouter(),auth=useAuthStore(),isMobile=ref(window.innerWidth<768),unread=ref(0);function resize(){isMobile.value=window.innerWidth<768}function logout(){auth.counselorLogout();router.push('/login')}onMounted(async()=>{window.addEventListener('resize',resize);try{unread.value=(await api.get('/counselor/notifications/unread-count')).data.count}catch(e){}});onUnmounted(()=>window.removeEventListener('resize',resize))</script>
<style scoped>.counselor-layout,.desktop-layout{height:100%}.desktop-layout{display:flex}.sidebar{width:220px;background:#f5f7fa;display:flex;flex-direction:column;border-right:1px solid #e4e7ed}.logo{padding:20px;font-size:18px;font-weight:700;text-align:center;color:#409eff}.sidebar .el-menu{border-right:0;flex:1}.menu-badge{margin-left:auto;margin-right:8px}.sidebar-footer{padding:12px;text-align:center}.main-content{flex:1;padding:24px;overflow-y:auto;background:#fff}.mobile-content{padding:16px 16px 76px;min-height:100%;box-sizing:border-box}.mobile-nav{position:fixed;bottom:0;left:0;right:0;height:60px;background:#fff;border-top:1px solid #e4e7ed;display:flex;z-index:100}.nav-item{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#909399;text-decoration:none;font-size:11px}.nav-item.router-link-active{color:#409eff}.nav-item .el-icon{font-size:20px;margin-bottom:3px}.mobile-nav :deep(.el-badge__content){transform:translate(45%,-35%) scale(.85)}</style>
